 * @return {boolean}
 */
var check = function(nums) {
    const n = nums.length;

    let i = 0;
    while (nums[i] >= nums[(i - 1 + n) % n]) {
        i = (i - 1 + n) % n;
    }

    for (let j = i; j < i + n - 1; j++) {
        if (nums[j] > nums[(j + 1) % n]) {
            return false;
        }
    }

    return true;
};

